<?php
require dirname(__DIR__).'/app/bootstrap.php';require_permission('payments.view');require dirname(__DIR__).'/app/layout.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{require_permission('payments.reverse');transaction(function(){$id=(int)($_POST['id']??0);$reason=required_text('reason',300);$p=one('SELECT * FROM payments WHERE id=? AND business_id=?',[$id,bid()]);if(!$p)throw new DomainException('Payment not found.');document_record((int)$p['document_id'],true);$p=one('SELECT * FROM payments WHERE id=? AND business_id=? FOR UPDATE',[$id,bid()]);if($p['reversed_at'])throw new DomainException('Payment has already been reversed.');query('UPDATE payments SET reversed_at=NOW(),reversal_reason=? WHERE id=? AND business_id=?',[$reason,$id,bid()]);audit('payment.reversed','payment',$id,['reason'=>$reason]);});flash('Payment reversed. The invoice balance has been updated.');redirect('payments.php');}catch(DomainException $ex){$error=$ex->getMessage();}}
$actions=can('payments.record')?'<a class="btn primary" href="invoices.php">'.icon('plus').' Record a payment</a>':'';if(can('payments.export'))$actions='<a class="btn" href="export.php?module=payments">'.icon('download').' Export</a>'.$actions;page_start('Payments','Every payment, accounted for. A clear view of your collections.',$actions);error_notice($error);
$search=mb_substr(trim($_GET['q']??''),0,100);$page=max(1,(int)($_GET['page']??1));$where='p.business_id=?';$params=[bid()];if($search!==''){$where.=' AND (c.name LIKE ? OR d.number LIKE ? OR p.reference LIKE ?)';$params=[...$params,'%'.$search.'%','%'.$search.'%','%'.$search.'%'];}$count=(int)scalar("SELECT COUNT(*) FROM payments p JOIN customers c ON c.id=p.customer_id JOIN documents d ON d.id=p.document_id WHERE $where",$params);$list=rows("SELECT p.*,c.name customer_name,d.number FROM payments p JOIN customers c ON c.id=p.customer_id AND c.business_id=p.business_id JOIN documents d ON d.id=p.document_id AND d.business_id=p.business_id WHERE $where ORDER BY p.payment_date DESC,p.id DESC LIMIT 15 OFFSET ".(($page-1)*15),$params);
?><section class="panel"><form class="list-toolbar"><div class="list-search"><?= icon('search') ?><input name="q" type="search" placeholder="Search customer, invoice or reference..." aria-label="Search payments" value="<?= e($search) ?>"></div><button class="btn"><?= icon('filter') ?> Filter</button></form><div class="table-scroll"><table><thead><tr><th>RECEIPT</th><th>CUSTOMER</th><th>INVOICE</th><th>DATE</th><th>AMOUNT</th><th>METHOD</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($list as $p): ?><tr><td><strong>PAY-<?= str_pad((string)$p['id'],4,'0',STR_PAD_LEFT) ?></strong><span class="sub"><?= e($p['reference']) ?></span></td><td><?= e($p['customer_name']) ?></td><td><a href="invoice-view.php?id=<?= $p['document_id'] ?>"><?= e($p['number']) ?></a></td><td><?= date_label($p['payment_date']) ?></td><td><strong><?= money($p['amount']) ?></strong></td><td><?= e($p['method']) ?></td><td><?= badge($p['reversed_at']?'Reversed':'Paid') ?></td><td><?php if(!$p['reversed_at']&&can('payments.reverse')): ?><form method="post" class="inline-actions" data-confirm="Reverse this payment? It will remain in history and the outstanding balance will increase."><?php csrf_field(); ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><input name="reason" required maxlength="300" placeholder="Reason" aria-label="Reversal reason"><button class="btn small danger">Reverse</button></form><?php endif; ?></td></tr><?php endforeach;if(!$list): ?><tr><td colspan="8" class="empty"><?= icon('credit-card') ?><h2>No payments recorded yet.</h2><p>Open an issued invoice to record its first payment.</p></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span><?= $count ?> payments · Page <?= $page ?></span><div class="pagination"><?php if($page>1): ?><a class="btn" href="?<?= e(http_build_query(['q'=>$search,'page'=>$page-1])) ?>">Previous</a><?php endif;if($page*15<$count): ?><a class="btn" href="?<?= e(http_build_query(['q'=>$search,'page'=>$page+1])) ?>">Next</a><?php endif; ?></div></div></section><?php page_end(); ?>
